import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { useJsonQuery } from "../../hooks/useApi";
import { ErrorDisplay } from "../../components/ErrorDisplay";
import { apiFetch, apiError } from "../../services/api";
import { TeacherDialog as RosterDialog, Download, Steps } from "./TeacherWorkbench";
import { BASE, type Row, type PageData, Table, Pager, QueryState, canWrite, useAction, ActionError, fileBase64, HelpTip, usePagination } from "./shared";
import "./student-workbench.css";

const columns = ["学校编号", "学校名称", "年级（1-12）", "班级号", "姓名", "账号", "学号", "班级座号", "性别", "科类", "类别", "中/高考号", "学籍号", "全国学籍号", "准考证号", "身份证", "手机号", "email", "应往届", "状态", "考场号", "考场座位号", "mac地址", "SN码", "住宿类型", "宿舍类型", "宿舍楼", "楼层", "宿舍号", "床号", "学生ID"];
const locked = ["学校编号", "学校名称", "姓名", "账号", "年级（1-12）", "班级号", "状态", "学生ID"];
const grades = ["小学一年级", "小学二年级", "小学三年级", "小学四年级", "小学五年级", "小学六年级", "初中一年级", "初中二年级", "初中三年级", "高中一年级", "高中二年级", "高中三年级", "复读班"];
const kindNames: Record<string, string> = { archive: "档案变更", promotion: "升级/换班", status: "离校/毕业/恢复在读", deletion: "误导入删除", identity: "姓名/账号变更" };
const taskStatuses: Record<string, string> = { ready: "待确认", invalid: "校验未通过", pending_review: "待身份审核", rejected: "审核未通过", cancelled: "已取消", succeeded: "已完成" };
const time = (value?: string) => value ? new Date(value).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false }) : "—";
type Initial = { kind: string; rows: Row[]; action?: string; returnTask?: string; mode?: string };
type Preparation = { identity_confirmed_ids: string[]; identity_uncertain_ids: string[]; anomaly_approvals: Record<string, string>; graduation_confirmed: boolean; graduation_student_ids: string[]; graduation_exclusions: Record<string, string>; duplicate_name_confirmed: boolean; records_verified_ids: string[] };
const emptyPreparation: Preparation = { identity_confirmed_ids: [], identity_uncertain_ids: [], anomaly_approvals: {}, graduation_confirmed: false, graduation_student_ids: [], graduation_exclusions: {}, duplicate_name_confirmed: false, records_verified_ids: [] };
function readPreparation(value: Record<string, unknown>): Preparation { return Object.fromEntries(Object.entries(emptyPreparation).map(([key, fallback]) => [key, value[key] ?? fallback])) as Preparation; }
const personId = (row: Row) => row.platform_id || row.fields?.["学生ID"] || "—";
function StudentStatus({ status }: { status: string }) { return <span className={`student-status student-status--${status}`}>{status === "active" ? "正常" : status === "graduated" ? "毕业" : "离校"}</span>; }
function Confirmation({ checked, onChange, children }: { checked: boolean; onChange: (value: boolean) => void; children: ReactNode }) { return <label className="teacher-confirm"><input type="checkbox" checked={checked} onChange={e => onChange(e.target.checked)} />{children}</label>; }
function StudentSnapshot({ row }: { row: Row }) { return <div className="teacher-snapshot"><div className="teacher-snapshot__title"><strong>{row.name || row.fields?.姓名}</strong><span className="teacher-id">学生ID：{personId(row)}</span></div><dl className="teacher-field-grid">{columns.map(field => <div key={field}><dt className={locked.includes(field) ? "student-locked" : ""}>{field}</dt><dd>{row.fields?.[field] || (field === "学生ID" ? personId(row) : "—")}</dd></div>)}</dl></div>; }

export function StudentWorkbench() {
  const [params, setParams] = useSearchParams();
  const [search, setSearch] = useState("");
  const [className, setClassName] = useState("");
  const [status, setStatus] = useState("");
  const pagination = usePagination(`${search}:${className}:${status}`);
  const query = useJsonQuery<PageData & { current_year: string }>(`${BASE}/roster/students/records?search=${encodeURIComponent(search)}&class_name=${encodeURIComponent(className)}&status=${status}&page=${pagination.page}&page_size=${pagination.pageSize}`);
  const context = useJsonQuery<Row>(`${BASE}/roster/students/context`);
  const selectionKey = `${search}:${className}:${status}:${pagination.page}:${pagination.pageSize}:${query.data?.items.map(r => r.id).join()}`;
  const [selection, setSelection] = useState<{ key: string; rows: Row[] }>({ key: "", rows: [] });
  const chosen = selection.key === selectionKey ? selection.rows : [];
  const [archive, setArchive] = useState<Row | null>(null);
  const [initial, setInitial] = useState<Initial | null>(null);
  const [notice, setNotice] = useState("");
  const visible = query.data?.items || [];
  const all = visible.length > 0 && chosen.length === visible.length;
  const check = useRef<HTMLInputElement>(null);
  useLayoutEffect(() => { if (check.current) check.current.indeterminate = chosen.length > 0 && !all; }, [chosen.length, all]);
  const view = params.get("student_view"), taskId = params.get("student_task") || "", batchId = params.get("student_batch") || "";
  const open = (next: string, id = "", returnTask = "") => {
    const values = new URLSearchParams(params);
    values.set("tab", "students"); values.set("student_view", next);
    ["student_task", "student_batch", "student_return"].forEach(key => values.delete(key));
    if (next === "task") values.set("student_task", id);
    if (next === "batch") values.set("student_batch", id);
    if (returnTask) values.set("student_return", returnTask);
    setParams(values);
  };
  const close = () => {
    const values = new URLSearchParams(params);
    const returning = values.get("student_return");
    ["student_view", "student_task", "student_batch", "student_return"].forEach(key => values.delete(key));
    if (returning) { values.set("student_view", "task"); values.set("student_task", returning); }
    setParams(values, { replace: true });
  };
  const completed = () => { setSelection({ key: "", rows: [] }); setNotice("办理完成，学生档案和操作记录已更新。"); };
  return <section className="teacher-workbench student-workbench" aria-label="学生档案">
    <div className="teacher-list-bar"><div className="teacher-list-bar__title"><h2>学生信息列表</h2><HelpTip label="办理说明"><Table headers={["办理事项", "页面入口"]}><tr><td>新增学生</td><td>右上角「导入学生」</td></tr><tr><td>普通档案字段</td><td>顶部「档案变更」，31 列整批更新</td></tr><tr><td>年级或班级</td><td>顶部「升级/换班」，5 列名单</td></tr><tr><td>离校、应届毕业、同学段恢复在读</td><td>行内「离校办理」或「恢复在读」；批量勾选后办理</td></tr><tr><td>姓名或账号</td><td>行内「姓名·账号变更」，每次仅改一项</td></tr><tr><td>误导入或多余记录</td><td>行内「误导入删除」或顶部批量操作</td></tr></Table><p>学生ID为平台统一分配的8～10位数字，仅用于数据关联和检索。改名、换账号、升级换班不改变ID；账号、学号、考号是独立字段。</p><p>真实有效的学生记录办理离校；资料修改使用对应变更流程。身份存疑提交当前事项的待审核任务，审核期间不更新学生。</p></HelpTip><span className="teacher-muted">共 {query.data?.total ?? "—"} 条</span></div>
      <div className="teacher-actions">{canWrite() && <><button disabled={!context.data} onClick={() => setInitial({ kind: "promotion", rows: chosen })}>升级/换班</button><button disabled={!context.data} onClick={() => setInitial({ kind: "archive", rows: chosen })}>档案变更</button><button disabled={!chosen.length || !context.data} onClick={() => setInitial({ kind: "status", rows: chosen })}>批量离校/毕业</button><button disabled={!chosen.length || !context.data} onClick={() => setInitial({ kind: "deletion", rows: chosen })}>批量误导入删除</button></>}<button onClick={() => open("records")}>操作记录</button>{canWrite() && <button className="teacher-primary" onClick={() => open("import")}>导入学生</button>}</div>
    </div>
    <div className="teacher-filters"><input aria-label="学生关键词" placeholder="关键词：学生ID / 姓名 / 登录账号 / 学号" value={search} maxLength={100} onChange={e => setSearch(e.target.value)} /><input aria-label="学生班级筛选" placeholder="班级名称 / 年级.班级" value={className} maxLength={100} onChange={e => setClassName(e.target.value)} /><select aria-label="学生状态" value={status} onChange={e => setStatus(e.target.value)}><option value="">全部状态</option><option value="active">正常</option><option value="departed">离校</option><option value="graduated">毕业</option></select></div>
    {notice && <p role="status" className="teacher-alert teacher-alert--ok">{notice}</p>}
    <ErrorDisplay error={context.error} />
    <QueryState query={query} empty={!visible.length}><div className="data-table-wrap"><table className="data-table teacher-table student-table"><thead><tr>{canWrite() && <th className="teacher-check"><input ref={check} type="checkbox" aria-label="选择本页全部学生" checked={all} disabled={!visible.length || query.isFetching} onChange={e => setSelection({ key: selectionKey, rows: e.target.checked ? visible : [] })} /></th>}<th>姓名 / 登录账号</th><th>班级</th><th>学号</th><th>学生ID</th><th>状态</th><th>操作</th></tr></thead><tbody>{visible.map(row => <tr key={row.id} className={row.status !== "active" ? "student-row-inactive" : ""}>{canWrite() && <td><input type="checkbox" aria-label={`选择学生${row.name}`} checked={chosen.some(r => r.id === row.id)} disabled={query.isFetching} onChange={e => setSelection({ key: selectionKey, rows: e.target.checked ? [...chosen, row] : chosen.filter(r => r.id !== row.id) })} /></td>}<td><strong>{row.name}</strong><small>{row.username || "未绑定登录账号"}</small></td><td>{row.grade || "—"}<small>{row.class_number || "—"}</small></td><td>{row.student_no || "—"}</td><td className="student-id-cell" title="平台唯一ID，与登录账号、学号和考号独立">{personId(row)}</td><td><StudentStatus status={row.status} /></td><td><div className="teacher-row-actions"><button onClick={() => setArchive(row)}>查看档案</button>{canWrite() && (row.status === "active" ? <><button className="student-identity-button" onClick={() => setInitial({ kind: "identity", rows: [row] })}>姓名·账号变更</button><button onClick={() => setInitial({ kind: "status", rows: [row], action: "depart" })}>离校办理</button><button className="teacher-danger" onClick={() => setInitial({ kind: "deletion", rows: [row] })}>误导入删除</button></> : <button className="student-restore-button" onClick={() => setInitial({ kind: "status", rows: [row], action: "restore" })}>恢复在读</button>)}</div></td></tr>)}</tbody></table></div></QueryState>
    {query.data && !query.error && <Pager {...pagination} total={query.data.total} />}
    {archive && <StudentArchive id={archive.id} onClose={() => setArchive(null)} onAction={kind => { setInitial({ kind, rows: [archive] }); setArchive(null); }} />}
    {initial && context.data && <InitialWorkflow initial={initial} context={context.data} filter={{ search, className }} onClose={() => { const returning = initial.returnTask; setInitial(null); if (returning) open("task", returning); }} onCreated={task => { const returning = initial.returnTask; setInitial(null); open("task", task.id, returning); }} />}
    {view === "records" && <StudentRecords onClose={close} onBatch={id => open("batch", id)} onTask={id => open("task", id)} />}
    {view === "import" && <StudentImport onClose={close} onComplete={completed} />}
    {view === "batch" && batchId && <StudentBatch id={batchId} onClose={close} onComplete={completed} />}
    {view === "task" && taskId && <StudentTask id={taskId} onClose={close} onComplete={completed} onRestart={task => { close(); setInitial({ kind: task.kind, mode: task.request_payload.mode, rows: task.snapshots.map((row: Row) => ({ ...row, name: row.fields.姓名, username: row.fields.账号, status: row.fields.状态 === "正常" ? "active" : row.fields.状态 === "毕业" ? "graduated" : "departed" })) }); }} onGraduate={rows => { close(); setInitial({ kind: "status", action: "graduate", rows: rows.map(row => ({ ...row, id: row.student_id, username: row.account, fields: { "年级（1-12）": row.grade, "班级号": row.class_number } })), returnTask: taskId }); }} />}
  </section>;
}

function StudentArchive({ id, onClose, onAction }: { id: string; onClose: () => void; onAction: (kind: string) => void }) {
  const query = useJsonQuery<Row>(`${BASE}/roster/students/records/${id}`);
  const row = query.data;
  return <RosterDialog title="学生档案详情（31 列）" drawer onClose={onClose} footer={<><button onClick={onClose}>关闭</button>{row && <Link to={`/admin/students/${id}`}>查看学情</Link>}{row?.status === "active" && canWrite() && <><button onClick={() => onAction("identity")}>姓名/账号变更</button><button className="teacher-danger" onClick={() => onAction("deletion")}>误导入删除</button></>}</>}><QueryState query={query}>{row && <><StudentStatus status={row.status} /><StudentSnapshot row={row} /><p className="teacher-muted">红色字段为锁定字段。普通资料请使用「档案变更」流程，年级班级请使用「升级/换班」。</p>{row.year_records?.length > 0 && <><h3>学年班级记录</h3><Table headers={["学年", "年级 / 班级", "状态"]}>{row.year_records.map((year: Row) => <tr key={year.academic_year}><td>{year.academic_year}</td><td>{year.grade} / {year.class_number}</td><td><StudentStatus status={year.status} /></td></tr>)}</Table></>}</>}</QueryState></RosterDialog>;
}

function FilePicker({ label, description, file, onFile, busy }: { label: string; description: string; file: File | null; onFile: (file: File | null) => void; busy: boolean }) {
  const input = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false), [error, setError] = useState<Error | null>(null);
  const pick = (next: File | null) => { setDragging(false); setError(null); if (next && (!/\.(xls|xlsx)$/i.test(next.name) || next.size > 5_000_000)) { onFile(null); setError(new Error(next.size > 5_000_000 ? "Excel 最大 5 MB、5000 行，请拆分。" : "仅支持 .xls / .xlsx 文件，请重新选择。")); return; } onFile(next); };
  return <div className="teacher-upload"><button type="button" className={`teacher-drop${dragging ? " is-dragging" : ""}`} disabled={busy} onClick={() => input.current?.click()} onDragOver={e => { e.preventDefault(); if (!busy) setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); if (!busy) pick(e.dataTransfer.files[0] || null); }}><strong>点击或拖拽上传</strong><span>《{label}.xlsx》</span><small>{description}</small></button><input ref={input} type="file" accept=".xls,.xlsx" aria-label={`上传${label}`} disabled={busy} onChange={e => { pick(e.target.files?.[0] || null); e.target.value = ""; }} />{file && <div className="teacher-file"><span><strong>{file.name}</strong> · {(file.size / 1024).toFixed(1)} KB</span><button disabled={busy} onClick={() => pick(null)}>移除重选</button></div>}<ErrorDisplay error={error} /></div>;
}

function InitialWorkflow({ initial, context, filter, onClose, onCreated }: { initial: Initial; context: Row; filter: { search: string; className: string }; onClose: () => void; onCreated: (task: Row) => void }) {
  const action = useAction();
  const [step, setStep] = useState(1), [file, setFile] = useState<File | null>(null), [reading, setReading] = useState(false);
  const [mode, setMode] = useState(initial.mode || "current"), [targetYear, setTargetYear] = useState(initial.mode === "next" ? context.next_year : context.current_year);
  const [statusAction, setStatusAction] = useState(initial.action || "depart");
  const [verified, setVerified] = useState(false), [uncertain, setUncertain] = useState(false), [incorrect, setIncorrect] = useState(false);
  const [field, setField] = useState("姓名"), [newValue, setNewValue] = useState(""), [reason, setReason] = useState("");
  const [deletionType, setDeletionType] = useState("incorrect"), [retained, setRetained] = useState<Record<string, string>>({});
  const [placements, setPlacements] = useState<Record<string, Record<string, string>>>(Object.fromEntries(initial.rows.map(row => [row.id, { grade: row.grade || row.fields?.["年级（1-12）"] || "", class_number: row.class_number || row.fields?.班级号 || "" }])));
  const busy = reading || action.isPending;
  const isFile = initial.kind === "archive" || initial.kind === "promotion";
  const labels = initial.kind === "archive" ? ["导出待变更资料", "上传变更文件", "校验与身份审核", "预览并确认"] : initial.kind === "promotion" ? ["选择办理分支", "上传名单", "校验与身份审核", "毕业办结与完整性", "年级异常审批", "预览并确认"] : initial.kind === "identity" ? ["身份核验", "选择变更项", "预览并确认"] : [initial.kind === "deletion" ? "身份核实与误导入核对" : "选类型与核对", "校验与预览", "完成"];
  const title = initial.kind === "identity" ? "学生姓名 / 账号变更（单条）" : initial.kind === "deletion" ? "学生误导入删除" : initial.kind === "status" ? "学生离校 / 毕业 / 恢复办理" : initial.kind === "archive" ? "学生档案变更（整批 · 31 列）" : "学生升级 / 换班（整批 · 5 列名单）";
  const exportPath = initial.rows.length ? `/roster/students/archive-template?${initial.rows.map(row => `student_ids=${row.id}`).join("&")}` : `/roster/students/archive-template?all_filtered=true&search=${encodeURIComponent(filter.search)}&class_name=${encodeURIComponent(filter.className)}`;
  const submit = async () => {
    setReading(true);
    try {
      const body = { kind: initial.kind, student_ids: initial.rows.map(row => row.id),
        ...(["promotion", "status"].includes(initial.kind) ? { mode, target_year: targetYear } : {}),
        ...(isFile && file ? { filename: file.name, content_base64: await fileBase64(file) } : {}),
        ...(initial.kind === "identity" ? { field, new_value: newValue, reason } : {}),
        ...(initial.kind === "status" ? { action: statusAction, placements } : {}),
        ...(initial.kind === "deletion" ? { reason, deletion_type: deletionType, retained_students: retained } : {}) };
      const created = await action.mutateAsync({ path: "/roster/students/tasks", body });
      if ((verified || uncertain) && !created.report.issues.length) {
        const ids = created.snapshots.map((row: Row) => row.id);
        const prepared = await action.mutateAsync({ path: `/roster/students/tasks/${created.id}/prepare`, body: { ...emptyPreparation, expected_revision: created.revision, identity_confirmed_ids: verified ? ids : [], identity_uncertain_ids: uncertain ? ids : [], records_verified_ids: incorrect ? ids : [] } });
        onCreated(prepared);
      } else onCreated(created);
    } catch { /* The mutation renders the actionable API error. */ } finally { setReading(false); }
  };
  const canSubmit = isFile ? !!file : initial.kind === "identity" ? !!newValue.trim() && !!reason.trim() : initial.kind === "deletion" ? (verified || uncertain) && incorrect && !!reason.trim() && (deletionType !== "duplicate" || initial.rows.every(row => retained[row.id])) : verified || uncertain;
  return <RosterDialog title={title} drawer={initial.kind === "status" || initial.kind === "deletion"} busy={busy} onClose={onClose} footer={<><button disabled={busy} onClick={onClose}>取消</button>{(isFile || initial.kind === "identity") && step === 1 ? <button className="teacher-primary" disabled={busy || (initial.kind === "identity" && !verified && !uncertain)} onClick={() => setStep(2)}>下一步：{isFile ? "上传文件" : "选择变更项"}</button> : <>{(isFile || initial.kind === "identity") && step > 1 && <button disabled={busy} onClick={() => setStep(1)}>上一步</button>}<button className="teacher-primary" disabled={!canSubmit || busy} onClick={() => void submit()}>{busy ? "正在校验…" : "开始校验与预览"}</button></>}</>}>
    <Steps labels={labels} step={step} /><ActionError action={action} />
    {initial.kind === "archive" && step === 1 && <><p>仅限学籍状态为「正常」的学生。31 列＝原 30 列＋末列【学生ID】；8 项锁定字段不可修改，其余 23 个普通字段填空即清空。</p><p className="teacher-alert teacher-alert--warn">{initial.rows.length ? `已选择 ${initial.rows.length} 名学生，将导出所选名单原值。` : "未勾选学生，将导出当前学生ID、姓名、账号、学号和班级筛选范围内的全部正常学生。"}</p><Download path={exportPath} filename="学生档案变更模板.xlsx">导出《学生档案变更模板.xlsx》（31 列，含原值）</Download><p className="teacher-muted">锁定：学校编号、学校名称、姓名、账号、年级（1-12）、班级号、状态、学生ID。</p></>}
    {initial.kind === "promotion" && step === 1 && <fieldset className="teacher-reasons"><legend>办理分支</legend><label><input type="radio" name="promotion-mode" checked={mode === "next"} onChange={() => { setMode("next"); setTargetYear(context.next_year); }} /><span>下一学年切换 · {context.next_year}<small>须先办结实际应届毕业名单，检查全部正常在读学生完整性；成功后同时切换全校当前学年。</small></span></label><label><input type="radio" name="promotion-mode" checked={mode === "current"} onChange={() => { setMode("current"); setTargetYear(context.current_year); }} /><span>当前学年调整 · {context.current_year}<small>仅列需调整或建档的学生；跳过全校毕业办结与名单完整性检查。</small></span></label></fieldset>}
    {isFile && step === 2 && <><FilePicker label={initial.kind === "archive" ? "学生档案变更模板" : "学生升级换班名单"} description={initial.kind === "archive" ? "31 列表头及顺序须与导出文件完全一致，学生ID必填且文件内唯一" : "5 列：学生ID、账号、姓名、目标年级、目标班级号；使用完整年级和班级名称"} file={file} onFile={setFile} busy={busy} /><p className="teacher-muted">支持 .xls / .xlsx，最大 5 MB、5000 行。任一行校验失败，整批不更新。</p>{initial.kind === "promotion" && <><Download path="/roster/students/promotion-template" filename="学生升级换班名单.xlsx">下载《升级换班名单模板.xlsx》</Download><p>目标学年：{targetYear}。学生ID唯一定位，姓名与账号须与原档案一致。</p></>}</>}
    {!isFile && <><div className="teacher-snapshot"><strong>{initial.rows.length === 1 ? `${initial.rows[0].name}（${initial.rows[0].username || "未绑定账号"}）` : `已选择 ${initial.rows.length} 名学生`}</strong><Table paginate headers={["学生ID", "姓名 / 账号", "年级 / 班级", "状态"]}>{initial.rows.map(row => <tr key={row.id}><td>{personId(row)}</td><td>{row.name}<small>{row.username}</small></td><td>{row.grade || row.fields?.["年级（1-12）"]}<small>{row.class_number || row.fields?.班级号}</small></td><td><StudentStatus status={row.status} /></td></tr>)}</Table></div>
      {initial.kind === "identity" && step === 1 && <><p>以学生ID定位，结合学号、学籍号或人工核验确认本人。姓名与账号都错误时，先核实是否误导入再走专用流程。</p><p>学号：{initial.rows[0].student_no || "—"} 学籍号：{initial.rows[0].fields?.学籍号 || "—"}</p></>}
      {initial.kind === "identity" && step === 2 && <><fieldset className="teacher-reasons"><legend>变更项（每次仅改一项）</legend>{["姓名", "账号"].map(value => <label key={value}><input type="radio" name="student-identity-field" checked={field === value} onChange={() => { setField(value); setNewValue(""); }} />{value} → 新{value}</label>)}</fieldset><label className="student-input-label">新{field}<input aria-label={`新${field}`} value={newValue} maxLength={100} onChange={e => setNewValue(e.target.value)} /></label><label className="student-input-label">变更原因<input aria-label="姓名账号变更原因" value={reason} maxLength={500} onChange={e => setReason(e.target.value)} /></label><p className="teacher-muted">账号变更保留原密码、学生ID和历史关联；旧账号立即失效，新账号接管。新姓名同班同名只提醒，核实后可保留。</p></>}
      {initial.kind === "status" && <><fieldset className="teacher-reasons"><legend>办理类型（每批仅一种）</legend>{[["depart", "离校"], ["graduate", "应届毕业"], ["restore", "恢复在读"]].map(([value, label]) => <label key={value}><input type="radio" name="student-status-action" checked={statusAction === value} onChange={() => { setStatusAction(value); setVerified(false); }} />{label}</label>)}</fieldset><label className="student-input-label">{statusAction === "restore" ? "返校目标学年" : "本批统一办理学年"}<select aria-label="办理学年" value={targetYear} onChange={e => { setTargetYear(e.target.value); setVerified(false); }}><option value={context.current_year}>当前学年 {context.current_year}</option><option value={context.next_year}>下一学年 {context.next_year}</option></select></label>{statusAction === "restore" && <><p>仅限同学段返校；跨学段入学请导入新增。一次确认恢复状态、启用原账号并新增或更新学年记录，不切换全校当前学年。</p><Table paginate headers={["姓名 / 学生ID", "返校年级", "返校班级", "原学段（无依据时核实）"]}>{initial.rows.map(row => <tr key={row.id}><td>{row.name}<small>{personId(row)}</small></td><td><select aria-label={`${row.name}返校年级`} value={placements[row.id]?.grade || ""} onChange={e => setPlacements({ ...placements, [row.id]: { ...placements[row.id], grade: e.target.value } })}><option value="">请选择年级</option>{grades.map(grade => <option key={grade}>{grade}</option>)}</select></td><td><input aria-label={`${row.name}返校班级`} value={placements[row.id]?.class_number || ""} placeholder="如1班" maxLength={100} onChange={e => setPlacements({ ...placements, [row.id]: { ...placements[row.id], class_number: e.target.value } })} /></td><td><select aria-label={`${row.name}原学段`} value={placements[row.id]?.source_segment || ""} onChange={e => { const next = { ...placements[row.id] }; if (e.target.value) next.source_segment = e.target.value; else delete next.source_segment; setPlacements({ ...placements, [row.id]: next }); }}><option value="">沿用原记录依据</option>{["小学", "初中", "高中"].map(value => <option key={value}>{value}</option>)}</select></td></tr>)}</Table></>}{statusAction === "graduate" && <div className="teacher-alert teacher-alert--warn">须逐人核对实际毕业名单，剔除仅离校、留级等非毕业学生。毕业候选：小学六年级、初中三年级、高中三年级及复读班。毕业后账号停用并归档，历史数据永久保留。</div>}{statusAction === "depart" && <p>离校后停用账号，保留学籍、成绩、错题和学情；无需区分休学、转学、退学原因。</p>}</>}
      {initial.kind === "deletion" && <><p className="teacher-alert teacher-alert--warn">仅限已核实的误导入或多余记录。资料有误使用对应变更流程，真实有效学生办理离校。</p><fieldset className="teacher-reasons"><legend>核实类型</legend><label><input type="radio" name="student-deletion-type" checked={deletionType === "incorrect"} onChange={() => setDeletionType("incorrect")} />误导入</label><label><input type="radio" name="student-deletion-type" checked={deletionType === "duplicate"} onChange={() => setDeletionType("duplicate")} />重复导入的多余记录</label></fieldset>{deletionType === "duplicate" && <><p>保留最早创建且已核实有效的一条，逐条指定保留记录的学生ID。</p>{initial.rows.map(row => <label className="student-input-label" key={row.id}>{row.name}的保留学生ID<input aria-label={`${row.name}保留学生ID`} value={retained[row.id] || ""} onChange={e => setRetained({ ...retained, [row.id]: e.target.value })} /></label>)}</>}<label className="student-input-label">核实依据<input aria-label="误导入核实依据" placeholder="调取原导入文件，与真实名单核对的结论" value={reason} maxLength={500} onChange={e => setReason(e.target.value)} /></label><Confirmation checked={incorrect} onChange={setIncorrect}>我已调取原文件并核实该记录确为误导入或多余记录。</Confirmation></>}
      {(step === 1 || initial.kind !== "identity") && <><Confirmation checked={verified} onChange={value => { setVerified(value); if (value) setUncertain(false); }}>{initial.kind === "identity" ? "我已核对学生身份，确认为本人。" : "我已逐人核对名单、学生ID、姓名和账号，身份确认无误。"}</Confirmation><Confirmation checked={uncertain} onChange={value => { setUncertain(value); if (value) setVerified(false); }}>身份存疑，先提交运营管理员身份审核；审核期间不更新学生。</Confirmation></>}
    </>}
  </RosterDialog>;
}

function ImportIssues({ batch }: { batch: Row }) { return <><div role="alert" className="teacher-alert teacher-alert--error"><strong>校验失败，整份退回</strong><p>本次未写入任何学生档案。修正全部错误后整表重传；账号重复无需先删除已有记录。</p></div><Table paginate headers={["行号 / 位置", "姓名 / 账号", "错误字段", "错误原因"]}>{batch.report.issues.map((row: Row, index: number) => <tr key={index}><td>{row.row_number ? `第${row.row_number}行` : "文件整体"}</td><td>{row.name}<small>{row.account}</small></td><td>{row.fields}</td><td>{row.message}<small>{row.suggestion}</small></td></tr>)}</Table><Download path={`/roster/imports/${batch.id}/errors`} filename="学生导入错误清单.xlsx">下载错误清单</Download></>; }
function ImportReceipt({ batch }: { batch: Row }) { return <><div role="status" className="teacher-alert teacher-alert--ok"><strong>导入完成</strong><p>成功 {batch.report.success_count} 条 · 放弃 {batch.report.skipped_count} 条</p><p>操作人：{batch.report.confirmed_by_name || batch.operator_name} · {time(batch.confirmed_at)}</p><p>批次：{batch.id}</p></div><Table paginate headers={["原文件行号", "账号", "学生ID"]}>{(batch.report.imported || []).map((row: Row) => <tr key={row.id}><td>{row.row_number}</td><td>{row.account}</td><td>{personId(row)}</td></tr>)}</Table>{batch.report.skipped_rows?.length > 0 && <p>主动放弃的行号：{batch.report.skipped_rows.join("、")}</p>}{batch.has_original ? <Download path={`/roster/imports/${batch.id}/original`} filename={batch.filename}>下载原文件</Download> : <p className="teacher-muted">该历史批次未保存原文件，可查看下方已保存的原始资料明细。</p>}<OriginalRows batch={batch} /></>; }

function OriginalRows({ batch }: { batch: Row }) {
  return <details className="teacher-preview"><summary>查看原始资料明细（30 列 · {batch.rows.length}行）</summary><Table paginate headers={["原文件行号", "原姓名 / 原账号", "原年级 / 班级", "完整原始资料"]}>{batch.rows.map((row: Row) => <tr key={row.row_number}><td>{row.row_number}</td><td>{row.values.姓名}<small>{row.values.账号}</small></td><td>{row.values["年级（1-12）"]}<small>{row.values.班级号}</small></td><td><details><summary>展开 30 列资料</summary><dl className="teacher-field-grid">{columns.filter(field => field !== "学生ID").map(field => <div key={field}><dt>{field}</dt><dd>{row.values[field] || row.values[field + " "] || "—"}</dd></div>)}</dl></details></td></tr>)}</Table></details>;
}

function StudentImport({ onClose, onComplete, initialBatch }: { onClose: () => void; onComplete: () => void; initialBatch?: Row }) {
  const action = useAction();
  const [batch, setBatch] = useState<Row | null>(initialBatch || null), [file, setFile] = useState<File | null>(null), [reading, setReading] = useState(false);
  const [step, setStep] = useState(initialBatch?.status === "succeeded" ? 4 : initialBatch ? 2 : 1);
  const [reviewed, setReviewed] = useState<Record<number, boolean>>({}), [decisions, setDecisions] = useState<Record<number, boolean>>({});
  const busy = reading || action.isPending;
  const reset = () => { setBatch(null); setFile(null); setStep(1); setReviewed({}); setDecisions({}); action.reset(); };
  const upload = async () => { if (!file) return; setReading(true); try { const result = await action.mutateAsync({ path: "/roster/students/imports", body: { filename: file.name, content_base64: await fileBase64(file) } }); setBatch(result); setStep(2); } catch { /* Displayed by ActionError. */ } finally { setReading(false); } };
  const confirm = async () => { if (!batch) return; try { const result = await action.mutateAsync({ path: `/roster/imports/${batch.id}/confirm`, body: { expected_revision: batch.revision, duplicate_decisions: Object.fromEntries(batch.report.suspicious.map((r: Row) => [r.row_number, decisions[r.row_number] ?? true])) } }); setBatch(result); setStep(4); onComplete(); } catch { try { const response = await fetchBatch(batch.id); setBatch(response); if (response.status === "invalid") setStep(2); } catch { /* Preserve the original mutation error. */ } } };
  return <RosterDialog title="导入学生（Excel 批量新增）" busy={busy} onClose={onClose} footer={<><button disabled={busy} onClick={onClose}>{step === 4 ? "关闭" : "取消"}</button>{step === 1 && canWrite() && <button className="teacher-primary" disabled={!file || busy} onClick={() => void upload()}>开始预校验</button>}{step === 2 && <><button disabled={busy} onClick={reset}>重新上传</button><button className="teacher-primary" disabled={!batch?.report.ok || busy || !canWrite()} onClick={() => setStep(3)}>下一步：同班同名确认</button></>}{step === 3 && <><button disabled={busy} onClick={reset}>重新上传</button><button className="teacher-primary" disabled={busy || !canWrite() || batch?.report.suspicious.some((row: Row) => !reviewed[row.row_number])} onClick={() => void confirm()}>{busy ? "正在整批入库…" : "确认入库"}</button></>}</>}>
    <Steps labels={["上传文件", "预校验与错误清单", "同班同名确认", "回执"]} step={step} /><ActionError action={action} />
    {step === 1 && <><FilePicker label="学生资料模板" description="30 列，列名与顺序完全一致；姓名、账号必填，账号唯一；状态仅接受正常" file={file} onFile={setFile} busy={busy} /><p>初始密码＝账号，首次登录强制修改；导入后每名学生生成独立学生ID。年级、班级不做字典匹配，其余字段可留空。</p><Download path="/roster/students/template" filename="学生资料模板.xlsx">下载《学生资料模板.xlsx》</Download></>}
    {step === 2 && batch && (batch.report.ok ? <div className="teacher-alert teacher-alert--ok">预校验通过，共 {batch.report.total_rows} 行。请继续核对 {batch.report.suspicious.length} 条同班同名提醒。</div> : <ImportIssues batch={batch} />)}
    {step === 3 && batch && <>{batch.report.suspicious.length ? <><h3>同班同名清单</h3><p>按姓名＋年级（1-12）＋班级号比对已有学生及文件内其他行。同班同名只提醒，核实为不同学生可保留；放弃的行不入库。</p><Table paginate headers={["原文件行号", "姓名 / 账号", "命中的记录", "选择与核实"]}>{batch.report.suspicious.map((row: Row) => <tr key={row.row_number}><td>{row.row_number}</td><td>{row.name}<small>{row.account}</small></td><td>{row.matches.map((match: Row, index: number) => <div key={index}>{match.name} / {match.account}<small>{match.row_number ? `文件内第${match.row_number}行` : `已有学生ID ${personId(match)}`} · {match.grade_class}</small></div>)}</td><td><select aria-label={`第${row.row_number}行同名处理`} value={decisions[row.row_number] === false ? "skip" : "keep"} onChange={e => setDecisions({ ...decisions, [row.row_number]: e.target.value === "keep" })}><option value="keep">保留该行</option><option value="skip">放弃该行</option></select><Confirmation checked={!!reviewed[row.row_number]} onChange={value => setReviewed({ ...reviewed, [row.row_number]: value })}>已核实本行选择</Confirmation></td></tr>)}</Table></> : <div className="teacher-alert teacher-alert--ok">未发现同班同名记录，可确认整批入库。</div>}<details className="teacher-preview"><summary>查看原文件资料明细（{batch.rows.length}行）</summary><Table paginate headers={["行号", "姓名 / 账号", "年级 / 班级", "学号"]}>{batch.rows.map((row: Row) => <tr key={row.row_number}><td>{row.row_number}</td><td>{row.values.姓名}<small>{row.values.账号}</small></td><td>{row.values["年级（1-12）"]} / {row.values.班级号}</td><td>{row.values.学号 || "—"}</td></tr>)}</Table></details></>}
    {step === 4 && batch && <ImportReceipt batch={batch} />}
  </RosterDialog>;
}

async function fetchBatch(id: string) { const response = await apiFetch(`${BASE}/roster/imports/${id}`); if (!response.ok) throw await apiError(response, "读取批次失败"); return response.json(); }
function StudentBatch({ id, onClose, onComplete }: { id: string; onClose: () => void; onComplete: () => void }) { const query = useJsonQuery<Row>(`${BASE}/roster/imports/${id}`); if (query.data) return <StudentImport key={id} initialBatch={query.data} onClose={onClose} onComplete={onComplete} />; return <RosterDialog title="学生导入回执" onClose={onClose}><QueryState query={query}>{null}</QueryState></RosterDialog>; }

function StudentTask({ id, onClose, onComplete, onGraduate, onRestart }: { id: string; onClose: () => void; onComplete: () => void; onGraduate: (rows: Row[]) => void; onRestart: (task: Row) => void }) {
  const query = useJsonQuery<Row>(`${BASE}/roster/students/tasks/${id}`);
  if (query.data) return <TaskFlow key={id} initialTask={query.data} onClose={onClose} onComplete={onComplete} onGraduate={onGraduate} onRestart={onRestart} refresh={async () => (await query.refetch()).data} />;
  return <RosterDialog title="学生办理任务" onClose={onClose}><QueryState query={query}>{null}</QueryState></RosterDialog>;
}

function TaskFlow({ initialTask, onClose, onComplete, onGraduate, onRestart, refresh }: { initialTask: Row; onClose: () => void; onComplete: () => void; onGraduate: (rows: Row[]) => void; onRestart: (task: Row) => void; refresh: () => Promise<Row | undefined> }) {
  const action = useAction();
  const [task, setTask] = useState(initialTask);
  const [prep, setPrep] = useState<Preparation>(readPreparation(initialTask.preparation));
  const isPromotion = task.kind === "promotion", isFile = isPromotion || task.kind === "archive";
  const last = isPromotion ? 6 : task.kind === "archive" ? 4 : task.kind === "identity" ? 3 : 2;
  const [step, setStep] = useState(initialTask.status === "succeeded" ? last + 1 : initialTask.report.ready_to_confirm ? last : isFile ? 3 : last);
  const [confirmed, setConfirmed] = useState(false), [reviewNote, setReviewNote] = useState(""), [reviewChosen, setReviewChosen] = useState<string[]>([]);
  const [anomalyChecked, setAnomalyChecked] = useState<Record<string, boolean>>(Object.fromEntries(Object.keys(initialTask.preparation.anomaly_approvals || {}).map(id => [id, true])));
  const report = task.report, pending: string[] = report.pending_review_ids || [];
  const identityIds: string[] = (report.identity_rows || []).map((row: Row) => row.id);
  const terminal = ["succeeded", "cancelled", "rejected"].includes(task.status);
  const busy = action.isPending;
  useEffect(() => { if (initialTask.revision > task.revision) { setTask(initialTask); setPrep(readPreparation(initialTask.preparation)); setConfirmed(false); } }, [initialTask, task.revision]);
  const hydrate = (next: Row) => { setTask(next); setPrep(readPreparation(next.preparation)); setConfirmed(false); };
  const update = async (overrides: Partial<Preparation> = {}) => {
    try { const next = await action.mutateAsync({ path: `/roster/students/tasks/${task.id}/prepare`, body: { ...prep, ...overrides, expected_revision: task.revision } }); hydrate(next); return next; } catch { const latest = await refresh(); if (latest) hydrate(latest); return null; }
  };
  const nextIdentity = async () => { const next = await update(); if (!next || next.report.issues.length || next.report.pending_review_ids.length || !next.report.identity_confirmed) return; setStep(isPromotion ? task.request_payload.mode === "next" ? 4 : 5 : last); };
  const cancel = async () => { try { hydrate(await action.mutateAsync({ path: `/roster/students/tasks/${task.id}/cancel`, body: { expected_revision: task.revision } })); } catch { /* Displayed by ActionError. */ } };
  const confirm = async () => { try { const next = await action.mutateAsync({ path: `/roster/students/tasks/${task.id}/confirm`, body: { expected_revision: task.revision, confirmed: true, identity_confirmed: true, changes_confirmed: true } }); hydrate(next); setStep(last + 1); onComplete(); } catch { const latest = await refresh(); if (latest) { hydrate(latest); if (latest.status === "invalid") setStep(isFile ? 3 : last); } } };
  const title = `学生${kindNames[task.kind]}${task.status === "succeeded" ? "办理回执" : "办理任务"}`;
  const labels = isPromotion ? ["选择办理分支", "上传名单", "校验与身份审核", "毕业办结与完整性", "年级异常审批", "预览并确认"] : task.kind === "archive" ? ["导出待变更资料", "上传变更文件", "校验与身份审核", "预览并确认"] : task.kind === "identity" ? ["身份核验", "选择变更项", "预览并确认"] : ["选类型与核对", "校验与预览", "完成"];
  const fullPreview = !isFile || step === last || terminal;
  return <RosterDialog title={title} drawer={task.kind === "status" || task.kind === "deletion"} busy={busy} onClose={onClose} footer={terminal ? <button onClick={onClose}>关闭</button> : <><button disabled={busy} onClick={onClose}>关闭，稍后继续</button>{canWrite() && <button disabled={busy} onClick={() => void cancel()}>取消本次办理</button>}{fullPreview && canWrite() && <button className={`teacher-primary${task.kind === "deletion" ? " student-delete-confirm" : ""}`} disabled={busy || !confirmed || !report.ready_to_confirm} onClick={() => void confirm()}>{busy ? "正在整批生效…" : task.kind === "archive" ? "确认整批更新" : task.kind === "deletion" ? "确认删除" : task.kind === "identity" ? "确认写入" : "确认生效"}</button>}</>}>
    <Steps labels={labels} step={step} /><p className="teacher-muted">批次 / 任务：{task.id} · {taskStatuses[task.status]}</p><ActionError action={action} />
    {task.status === "succeeded" && <div role="status" className="teacher-alert teacher-alert--ok"><strong>办理完成</strong><p>成功 {report.success_count} 名学生 · 确认人：{report.confirmed_by_name || task.operator_name} · {time(task.confirmed_at)}</p>{task.kind === "promotion" && task.request_payload.mode === "next" && <p>全校当前学年已切换为 {task.request_payload.target_year}。</p>}{task.kind === "identity" && task.request_payload.field === "账号" && <p>旧账号立即失效，新账号接管；原密码、学生ID和历史关联保留。</p>}{task.kind === "deletion" && <p>档案与关联个人数据已删除，账号已释放；原档案快照、原账号、导入批次和处置结果长期保留。</p>}</div>}
    {task.status === "cancelled" && <div role="status" className="teacher-alert teacher-alert--warn">本次办理已取消，未更新学生档案、账号或历史数据。</div>}
    {task.status === "rejected" && <div role="status" className="teacher-alert teacher-alert--error">身份审核未通过，本次办理已结束，未更新任何学生。</div>}
    {report.issues.length > 0 && <><div role="alert" className="teacher-alert teacher-alert--error"><strong>校验失败，整批退回</strong><p>本批未更新任何学生。修正错误后重新办理；字段变更须重新导出现有资料。</p></div><Table paginate headers={["行号", "姓名 / 账号", "学生ID", "错误原因"]}>{report.issues.map((row: Row, index: number) => <tr key={index}><td>{row.row_number || "文件"}</td><td>{row.name}<small>{row.account}</small></td><td>{row.student_id || "—"}</td><td>{row.message}<small>{row.fields} · {row.suggestion}</small></td></tr>)}</Table><div className="teacher-nav"><Download path={`/roster/students/tasks/${task.id}/errors`} filename="学生办理错误清单.xlsx">下载错误清单</Download>{!terminal && canWrite() && <button disabled={busy} onClick={() => onRestart(task)}>修正后重新办理</button>}</div></>}
    {!terminal && !report.issues.length && (step === 3 && isFile || !isFile && !report.ready_to_confirm || pending.length > 0) && <section>
      <h3>学生身份核验</h3><p>以学生ID定位，结合学号、学籍号或原导入文件确认本人。无法确认时标为存疑，提交本事项待审核任务。</p>
      <Table paginate headers={["学生ID", "姓名 / 账号", "学号 / 学籍号", "核验"]}>{report.identity_rows.map((row: Row) => <tr key={row.id}><td>{personId(row)}</td><td>{row.name}<small>{row.account}</small></td><td>{row.student_no || "—"}<small>{row.registration_no || "—"}</small></td><td>{task.reviews[row.id]?.status === "approved" ? <span className="student-review-approved">审核已通过</span> : <Confirmation checked={prep.identity_uncertain_ids.includes(row.id) || task.reviews[row.id]?.status === "pending"} onChange={value => setPrep({ ...prep, identity_uncertain_ids: value ? [...new Set([...prep.identity_uncertain_ids, row.id])] : prep.identity_uncertain_ids.filter(id => id !== row.id), identity_confirmed_ids: prep.identity_confirmed_ids.filter(id => id !== row.id) })}>身份存疑</Confirmation>}{row.source_import_id && (row.source_import_has_original ? <Download path={`/roster/imports/${row.source_import_id}/original`} filename="原学生导入文件.xlsx">调取原导入文件</Download> : <small>历史原文件未保存，原批次：{row.source_import_id}；可在操作记录查看原始资料。</small>)}</td></tr>)}</Table>
      {canWrite() && <><Confirmation checked={identityIds.length > 0 && identityIds.filter(id => !prep.identity_uncertain_ids.includes(id) && !pending.includes(id)).every(id => prep.identity_confirmed_ids.includes(id)) && prep.identity_confirmed_ids.length > 0} onChange={value => setPrep({ ...prep, identity_confirmed_ids: value ? identityIds.filter(id => !prep.identity_uncertain_ids.includes(id) && !pending.includes(id)) : [] })}>我已逐人核对本批名单，除标为存疑的记录外，均确认是本人。</Confirmation>{task.kind === "deletion" && <Confirmation checked={identityIds.every(id => prep.records_verified_ids.includes(id))} onChange={value => setPrep({ ...prep, records_verified_ids: value ? identityIds : [] })}>我已调取原导入文件，核实本批记录确为误导入或多余记录。</Confirmation>}<div className="teacher-nav"><button className="teacher-primary" disabled={busy || !identityIds.every(id => prep.identity_confirmed_ids.includes(id) || prep.identity_uncertain_ids.includes(id) || task.reviews[id]?.status === "approved" || task.reviews[id]?.status === "pending")} onClick={() => void nextIdentity()}>{prep.identity_uncertain_ids.length ? "保存核验并提交身份审核" : "保存核验，继续预览"}</button></div></>}
    </section>}
    {pending.length > 0 && !terminal && <section className="student-review-box"><h3>待审核任务 · 运营管理员身份审核</h3><p>审核期间不更新学生。审核通过后回本流程继续，未通过则结束。</p><Table paginate headers={["选择", "学生ID", "姓名 / 账号"]}>{report.identity_rows.filter((row: Row) => pending.includes(row.id)).map((row: Row) => <tr key={row.id}><td><input aria-label={`审核学生${row.name}`} type="checkbox" checked={reviewChosen.includes(row.id)} onChange={e => setReviewChosen(e.target.checked ? [...reviewChosen, row.id] : reviewChosen.filter(id => id !== row.id))} /></td><td>{personId(row)}</td><td>{row.name}<small>{row.account}</small></td></tr>)}</Table>{canWrite() && <><label className="student-input-label">核验依据<input aria-label="身份审核依据" value={reviewNote} maxLength={500} placeholder="核对系统原档案、学号、学籍号和本次文件的结论" onChange={e => setReviewNote(e.target.value)} /></label><div className="teacher-nav">{[["rejected", "审核未通过，结束办理"], ["approved", "审核通过，返回原流程"]].map(([decision, label]) => <button key={decision} className={decision === "approved" ? "teacher-primary" : "teacher-danger"} disabled={busy || !reviewChosen.length || !reviewNote.trim()} onClick={async () => { try { hydrate(await action.mutateAsync({ path: `/roster/students/tasks/${task.id}/review`, body: { expected_revision: task.revision, student_ids: reviewChosen, decision, note: reviewNote } })); setReviewChosen([]); } catch { /* Displayed by ActionError. */ } }}>{label}</button>)}</div></>}</section>}
    {isPromotion && step === 4 && !terminal && <section><h3>应届毕业办结与全校名单完整性</h3><p>逐人核对实际应届毕业名单，剔除留级等非毕业学生。实际毕业学生须先在离校办理中完成毕业。</p><Table paginate headers={["实际毕业", "姓名 / 账号", "年级 / 班级", "非毕业剔除依据"]}>{report.graduation_candidates.map((row: Row) => <tr key={row.student_id}><td><input aria-label={`${row.name}属于实际毕业名单`} type="checkbox" checked={prep.graduation_student_ids.includes(row.student_id)} onChange={e => { setPrep({ ...prep, graduation_student_ids: e.target.checked ? [...prep.graduation_student_ids, row.student_id] : prep.graduation_student_ids.filter(id => id !== row.student_id), graduation_confirmed: false }); }} /></td><td>{row.name}<small>{row.account}</small><StudentStatus status={row.status} /></td><td>{row.grade}<small>{row.class_number}</small></td><td>{!prep.graduation_student_ids.includes(row.student_id) && row.status === "active" && <input aria-label={`${row.name}非毕业依据`} value={prep.graduation_exclusions[row.student_id] || ""} maxLength={500} placeholder="如已核实留级，填写依据" onChange={e => setPrep({ ...prep, graduation_exclusions: { ...prep.graduation_exclusions, [row.student_id]: e.target.value } })} />}</td></tr>)}</Table><Confirmation checked={prep.graduation_confirmed} onChange={value => setPrep({ ...prep, graduation_confirmed: value })}>我已逐人核对实际毕业名单，非毕业学生已剔除并记录依据。</Confirmation>
      {report.pending_graduations.length > 0 && <><div className="teacher-alert teacher-alert--warn">实际毕业名单还有 {report.pending_graduations.length} 名学生未办结，完成毕业后返回继续核验。</div><button className="teacher-primary" disabled={busy} onClick={() => onGraduate(report.pending_graduations)}>先办理这批应届毕业</button></>}
      {report.missing.length > 0 && <><div role="alert" className="teacher-alert teacher-alert--warn">全校正常在读名单遗漏 {report.missing.length} 名学生。补齐前不切换学年。</div><Table paginate headers={["姓名 / 账号", "学生ID", "原年级 / 班级"]}>{report.missing.map((row: Row) => <tr key={row.student_id}><td>{row.name}<small>{row.account}</small></td><td>{personId(row)}</td><td>{row.grade}<small>{row.class_number}</small></td></tr>)}</Table><button disabled={busy} onClick={() => onRestart(task)}>返回补齐名单</button></>}
      <div className="teacher-nav"><button disabled={busy} onClick={() => setStep(3)}>上一步</button><button className="teacher-primary" disabled={busy || !prep.graduation_confirmed || report.graduation_candidates.some((row: Row) => row.status === "active" && !prep.graduation_student_ids.includes(row.student_id) && !prep.graduation_exclusions[row.student_id]?.trim())} onClick={async () => { const next = await update(); if (next && !next.report.issues.length && !next.report.pending_graduations.length && !next.report.missing.length && !next.report.graduation_exclusions_missing.length) setStep(5); }}>重新核验毕业办结与名单完整性</button></div>
    </section>}
    {((isPromotion && step === 5) || (!isFile && report.anomalies.length > 0 && !report.anomalies_approved)) && !terminal && <section><h3>年级异常复核审批</h3>{report.anomalies.length ? <><p>逐条核实身份、原年级、目标年级及留级、跳级或年级变动依据，全部审批通过后继续。</p><Table paginate headers={["姓名 / 账号", "原年级 → 目标年级", "核实依据", "审批"]}>{report.anomalies.map((row: Row) => <tr key={row.student_id}><td>{row.name}<small>{row.account}</small></td><td>{row.before || "无可比记录"} → {row.after}<small>{row.message}</small></td><td><input aria-label={`${row.name}年级异常依据`} value={prep.anomaly_approvals[row.student_id] || ""} maxLength={500} onChange={e => { setPrep({ ...prep, anomaly_approvals: { ...prep.anomaly_approvals, [row.student_id]: e.target.value } }); setAnomalyChecked({ ...anomalyChecked, [row.student_id]: false }); }} /></td><td><Confirmation checked={!!anomalyChecked[row.student_id]} onChange={value => setAnomalyChecked({ ...anomalyChecked, [row.student_id]: value })}>已复核并审批通过</Confirmation></td></tr>)}</Table></> : <div className="teacher-alert teacher-alert--ok">本批无年级异常，无需复核审批。</div>}<div className="teacher-nav">{isPromotion && <button disabled={busy} onClick={() => setStep(task.request_payload.mode === "next" ? 4 : 3)}>上一步</button>}<button className="teacher-primary" disabled={busy || report.anomalies.some((row: Row) => !anomalyChecked[row.student_id] || !prep.anomaly_approvals[row.student_id]?.trim())} onClick={async () => { const next = await update(); if (next?.report.anomalies_approved) setStep(last); }}>保存审批，下一步：预览</button></div></section>}
    {fullPreview && <>
      <h3>{terminal ? "办理明细" : "执行前预览"}</h3>
      {report.changes.length > 0 && <><p>仅列变化字段 · 影响 {report.affected_students} 名学生 · 将清空 {report.clear_count} 项</p><Table paginate headers={["姓名 / 学生ID", "字段", "原值", "新值 / 将清空"]}>{report.changes.map((row: Row, index: number) => <tr key={index}><td>{row.name}<small>{personId(row)}</small></td><td>{row.field}</td><td>{row.before || "（空）"}</td><td className={row.clear ? "student-cleared" : "teacher-changed"}>{row.clear ? "将清空" : row.after}</td></tr>)}</Table></>}
      {task.kind === "identity" && <><p>变更原因：{task.request_payload.reason}</p>{report.duplicates.length > 0 && <><div className="teacher-alert teacher-alert--warn">新姓名与其他学生同班同名，核实为不同学生后可保留。</div><Table headers={["姓名 / 账号", "学生ID", "年级 / 班级"]}>{report.duplicates.map((row: Row) => <tr key={row.student_id}><td>{row.name}<small>{row.account}</small></td><td>{personId(row)}</td><td>{row.grade} / {row.class_number}</td></tr>)}</Table>{!terminal && canWrite() && <><Confirmation checked={prep.duplicate_name_confirmed} onChange={value => setPrep({ ...prep, duplicate_name_confirmed: value })}>我已核实同班同名为不同学生，确认保留新姓名。</Confirmation><button disabled={busy || !prep.duplicate_name_confirmed} onClick={() => void update()}>保存同名核对结果</button></>}</>}</>}
      {report.placements.length > 0 && <Table paginate headers={["姓名 / 学生ID", "目标学年", "年级 / 班级前后值", "学年记录", "目标状态 / 账号"]}>{report.placements.map((row: Row) => <tr key={row.student_id}><td>{row.name}<small>{personId(row)}</small></td><td>{row.target_year}</td><td>{row.old_grade} {row.old_class} →<small>{row.grade} {row.class_number}</small></td><td>{row.operation}</td><td><StudentStatus status={row.target_status} /><small>账号{row.account_enabled ? "启用" : "停用"}{row.archived ? " · 毕业归档" : ""}</small></td></tr>)}</Table>}
      {task.kind === "promotion" && <p className="teacher-alert teacher-alert--warn">{task.request_payload.mode === "next" ? `成功后同时切换全校当前学年为 ${task.request_payload.target_year}。` : `本次仅调整 ${task.request_payload.target_year} 学年记录。`}历史成绩、错题与学情保留考试发生时的学年班级归属。</p>}
      {task.kind === "status" && task.request_payload.action === "restore" && <p className="teacher-alert teacher-alert--warn">沿用原学生ID与账号；恢复正常、启用账号并新增或更新学年记录同时生效，毕业生撤销归档。不切换全校当前学年。</p>}
      {task.kind === "deletion" && <><p>核实依据：{task.request_payload.reason}</p><p className="teacher-alert teacher-alert--warn">删除所选账号、档案、学年记录及关联个人数据，保留考试、班级和其他学生。仅重算实际参与的考试及对应统计、报告。</p><Table headers={["数据类型", "条数"]}>{report.affected.map((row: Row) => <tr key={row.type}><td>{row.label}</td><td>{row.count}</td></tr>)}</Table>{!report.affected.some((row: Row) => ["student_exam_scores", "student_subject_scores", "question_scores", "diagnosis_reports", "education_reviews", "chat_sessions"].includes(row.type)) && <p>成绩 / 错题 / 学情：无关联数据。</p>}<h3>受影响考试及重算范围</h3>{report.affected_exams.length ? <Table headers={["考试", "学年", "重算范围"]}>{report.affected_exams.map((row: Row) => <tr key={row.id}><td>{row.name}<small>{row.id}</small></td><td>{row.academic_year || "—"}</td><td>{row.scope}<small>班级：{row.classes?.join("、")} · 年级：{row.grades?.join("、")}</small></td></tr>)}</Table> : <p>无受影响考试，不重算无关统计。</p>}{report.disposition && <p>已删除 {report.disposition.deleted_students} 名学生和 {report.disposition.deleted_accounts} 个账号；重算 {report.disposition.recalculated_exam_ids.length} 次考试，刷新 {report.disposition.refreshed_report_statistics} 份报告统计。</p>}</>}
      {!terminal && canWrite() && <Confirmation checked={confirmed} onChange={setConfirmed}>{task.kind === "deletion" ? "我已核对影响范围与重算范围，确认执行删除（二次确认）。" : task.kind === "archive" ? "我已核对全部变化字段与将清空项，确认整批更新。" : "我已核对原值、新值、身份、办理范围及原因，确认整批生效；失败不部分写入。"}</Confirmation>}
      {!terminal && !report.ready_to_confirm && <p className="teacher-muted">须完成身份核验、适用的同名确认、毕业办结、名单完整性及年级异常审批后才能生效。</p>}
    </>}
    <details className="teacher-preview"><summary>{task.kind === "deletion" ? "原档案快照与导入批次（长期保留）" : "原档案与办理来源"} · {task.snapshots.length} 名学生</summary>{task.snapshots.map((row: Row) => <details key={row.id}><summary>{row.fields.姓名} / {row.fields.账号} · 学生ID：{personId(row)}</summary><StudentSnapshot row={row} /><p>原创建时间：{time(row.created_at)}</p>{row.source_import_id && <><p>原导入批次：{row.source_import_id}</p>{row.source_import_has_original ? <Download path={`/roster/imports/${row.source_import_id}/original`} filename="原学生导入文件.xlsx">调取原导入文件</Download> : <p className="teacher-muted">历史原文件未保存，可在操作记录中查看原始资料明细。</p>}</>}</details>)}</details>
    {Object.keys(task.reviews).length > 0 && <details className="teacher-preview"><summary>身份审核记录</summary><Table headers={["学生ID", "审核结果", "依据 / 审核人 / 时间"]}>{Object.entries(task.reviews).map(([id, value]) => { const row = value as Row; return <tr key={id}><td>{id}</td><td>{row.status === "approved" ? "通过" : row.status === "rejected" ? "未通过" : "待审核"}</td><td>{row.note || "—"}<small>{row.reviewer_id || "—"} · {time(row.reviewed_at)}</small></td></tr>; })}</Table></details>}
    {task.has_original && <Download path={`/roster/students/tasks/${task.id}/original`} filename={task.filename}>下载本次办理原文件</Download>}
  </RosterDialog>;
}

function StudentRecords({ onClose, onBatch, onTask }: { onClose: () => void; onBatch: (id: string) => void; onTask: (id: string) => void }) {
  const [tab, setTab] = useState("imports"), [search, setSearch] = useState(""), [kind, setKind] = useState("");
  const pagination = usePagination(`${tab}:${search}:${kind}`);
  const imports = useJsonQuery<PageData>(`${BASE}/roster/students/imports?paginated=true&search=${encodeURIComponent(search)}&page=${pagination.page}&page_size=${pagination.pageSize}`, tab === "imports");
  const tasks = useJsonQuery<PageData>(`${BASE}/roster/students/tasks?search=${encodeURIComponent(search)}&kind=${kind}&page=${pagination.page}&page_size=${pagination.pageSize}`, tab === "tasks");
  const query = tab === "imports" ? imports : tasks;
  return <RosterDialog title="学生操作记录" drawer onClose={onClose} footer={<button onClick={onClose}>关闭</button>}><div className="teacher-record-tabs"><button className={tab === "imports" ? "active" : ""} onClick={() => { setTab("imports"); setSearch(""); }}>导入回执</button><button className={tab === "tasks" ? "active" : ""} onClick={() => { setTab("tasks"); setSearch(""); }}>办理记录 / 待审核任务</button></div><div className="teacher-filters"><input aria-label="搜索学生操作记录" placeholder={tab === "imports" ? "文件名 / 姓名 / 账号 / 批次" : "姓名 / 原账号 / 新账号 / 学生ID / 批次"} value={search} maxLength={100} onChange={e => setSearch(e.target.value)} />{tab === "tasks" && <select aria-label="学生办理记录类型" value={kind} onChange={e => setKind(e.target.value)}><option value="">全部类型</option>{Object.entries(kindNames).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>}</div><QueryState query={query} empty={!query.data?.items.length}>{query.data?.items.map(row => <article key={row.id} className="teacher-record"><div className="teacher-record__head"><strong>{tab === "imports" ? "批量导入" : row.kind_label}</strong><span className="teacher-tag">{taskStatuses[row.status] || row.status}</span></div><p className="teacher-muted">批次：{row.id}<br />操作人：{row.operator_name} · {time(row.confirmed_at || row.created_at)}</p>{tab === "imports" ? <><p>文件：{row.filename}</p><p>成功 {row.report.success_count ?? "—"} 条 · 放弃 {row.report.skipped_count ?? "—"} 条</p><div className="teacher-record__actions"><button onClick={() => onBatch(row.id)}>{row.status === "succeeded" ? "查看导入明细" : "查看校验与继续办理"}</button>{row.has_original && <Download path={`/roster/imports/${row.id}/original`} filename={row.filename}>下载原文件</Download>}</div></> : <><p>涉及 {row.report.identity_rows?.length || 0} 名学生{row.request_payload.target_year ? ` · 目标学年 ${row.request_payload.target_year}` : ""}</p><p className="teacher-muted">{row.report.identity_rows?.slice(0, 3).map((student: Row) => `${student.name}（${student.account}）`).join("、")}</p>{row.status === "pending_review" && <p className="student-cleared">待审核 {row.report.pending_review_ids.length} 条；审核期间不更新学生。</p>}<div className="teacher-record__actions"><button onClick={() => onTask(row.id)}>{row.status === "pending_review" ? "进入身份审核" : row.status === "ready" ? "继续办理" : "查看办理明细"}</button>{row.has_original && <Download path={`/roster/students/tasks/${row.id}/original`} filename={row.filename}>下载原文件</Download>}</div></>}</article>)}</QueryState>{query.data && !query.error && <Pager {...pagination} total={query.data.total} />}</RosterDialog>;
}
